/* Public results are opt-in; deterministic verification runs separately from the local save. */
const Ranked=ShopReplay;
Ranked.installRecording();
currentBankAssessment=function(){return ShopUnderwriting.assess(state);};
let rankSyncPromise=null,rankMessage='',rankScenario=null,rankSynced=0;
const safeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function rankRequest(path,data){const r=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined});let body;try{body=await r.json();}catch{throw Error('通信を確認して、もう一度接続してください。');}if(!r.ok)throw Error(body.error||'接続できませんでした。');return body;}
async function commandHash(command){const a=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(command)));return [...new Uint8Array(a)].map(x=>x.toString(16).padStart(2,'0')).join('');}
function rankedStatus(){const r=state.replay;return r?`月替わり ${r.scenario} · 検証済み ${rankSynced}/${r.ops.length}操作${rankMessage?' · '+rankMessage:''}`:'通常プレイ · 自己ベスト対象';}
function updateRankStatus(){const target=el('rankStatus');if(target)target.textContent=rankedStatus();}
async function syncRanked(){if(!state.replay)return;if(rankSyncPromise)return rankSyncPromise;const id=state.replay.id;rankSyncPromise=(async()=>{const status=await rankRequest('/api/run/'+id);if(state.replay?.id!==id)return;let cursor=status.revision;if(cursor>state.replay.ops.length||cursor&&status.lastHash!==await commandHash(state.replay.ops[cursor-1]))throw Error('サーバーと異なる履歴です。このセーブは通常プレイとして続けられます。');rankSynced=cursor;while(state.replay?.id===id&&cursor<state.replay.ops.length){const r=await rankRequest('/api/run/'+id+'/step',{revision:cursor,command:state.replay.ops[cursor]});cursor=r.revision;rankSynced=cursor;updateRankStatus();}rankMessage='同期済み';})().catch(err=>{rankMessage=err.message;throw err;}).finally(()=>{rankSyncPromise=null;updateRankStatus();});return rankSyncPromise;}
const saveBeforeRanked=saveGame;
saveGame=function(){saveBeforeRanked();if(state.replay)syncRanked().catch(()=>{});};
async function showRanking(){openShop('月替わりチャレンジと公開ランキング','<p>ランキングを読み込んでいます…</p>');try{rankScenario=await rankRequest('/api/scenario');const r=await rankRequest('/api/ranking?scenario='+rankScenario.scenario);openShop('月替わりチャレンジと公開ランキング',`<p><b>${safeText(r.scenario)}の共通シナリオ</b>。同じ天候・物件候補から10年間を経営します。操作はサーバーでも再計算し、点数や預金を端末で書き換えても公開順位には反映されません。</p><p id="rankStatus">${safeText(rankedStatus())}</p><button id="rankStartPreview">今月のチャレンジを始める</button>${state.replay?'<button id="rankRetry">未送信の操作を再同期</button><button id="rankPublishPreview">完走記録の公開を確認する</button><button id="rankWithdrawPreview">自分の公開記録を取り下げる</button>':''}<p>新しいチャレンジは現在のゲームと入れ替わります。開始前のゲームは復元用に１世代保存します。既存セーブは通常プレイを続けられますが、途中から公開順位には登録できません。</p><div class="trend-scroll"><table class="trend-table"><thead><tr><th>順位・表示名</th><th>総合</th><th>収益性</th><th>健全性</th><th>個人資産</th></tr></thead><tbody>${r.rows.map((x,i)=>`<tr><th><button data-rank-detail="${safeText(x.id)}">${i+1}位 ${safeText(x.name)}</button></th><td>${x.score}/300</td><td>${x.profitability}</td><td>${x.health}</td><td>${x.wealth}</td></tr>`).join('')||'<tr><td colspan="5">まだ公開された完走記録はありません。</td></tr>'}</tbody></table></div><label>過去のシナリオ（月）<input id="rankMonth" type="month" value="${r.scenario}"></label><button id="rankLoadMonth">この月の順位を見る</button><p>点数が同じ場合は公開が早い記録を先に表示。同じブラウザからは各シナリオの自己最高を１件掲載します。表示名はニックネームで、本人確認はしていません。通常プレイの個人預金や仕訳を自動で公開しません。</p>`);}catch(err){openShop('ランキングへの接続',`<p>${safeText(err.message)}</p><p>ゲームの保存データは残っています。</p><button id="rankingMenuRetry">再接続する</button>`);}}
async function startRanked(){const salary=readStartingSalary('rankStartingSalary');if(!rankScenario)throw Error('シナリオを読み直してください。');const r=await rankRequest('/api/start',{scenario:rankScenario.scenario});const old=localStorage.getItem(SAVE_KEY);if(old)localStorage.setItem(SAVE_KEY+'-before-restore',old);state=Ranked.create(r.seed);state.replay={id:r.id,seed:r.seed,scenario:r.scenario,engine:r.engine,ops:[]};state=E.extension.setSalary(state,salary);introComplete=true;monthClosed=false;lastReport=null;statementReport=null;animationQueue=[];seenEntries=new Set();choice={quantities:E.recommend(state),price:'list',action:'tend',orderSource:'recommended'};rankSynced=0;rankMessage='同期済み';closeShop();el('intro').classList.add('hidden');document.querySelector('.shell').inert=false;el('report').classList.remove('show');document.querySelector('.top').inert=false;el('planning').inert=false;document.body.style.overflow='';saveGame();renderPlanning();}
function publishRankPreview(){const r=Ranked.snapshot(state);if(!state.replay||!r.score||['offer','negotiate','confirm'].includes(state.expansion.ma?.phase))throw Error('チャレンジを10年間完走し、商談を終えてから公開できます。');openShop('完走記録を公開しますか？',`<p>公開する内容：表示名、３軸の点数・個人資産額・売却額、最後の３期の決算、事業別収支、事業構成、M&Aの結果。仕訳ログや操作履歴そのものは公開しません。</p><p>記録はサーバーが再計算した数値で公開されます。このシナリオの過去の自己最高を下回る場合は、最高記録を残します。</p><label>ニックネーム（20文字以内）<input id="rankNickname" type="text" maxlength="20" autocomplete="off" placeholder="クエの釣具店"></label><button id="rankPublishConfirm">この内容で公開する</button><p>あとで同じブラウザから公開を取り下げられます。Cookieを削除したり別端末に移ると、同じ記録の操作権限は引き継げません。</p>`);}
async function showRankDetail(id){const r=await rankRequest('/api/ranking/'+id),s=r.snapshot;openShop(safeText(r.name)+'の経営記録',`<p>${safeText(r.scenario)} · ${s.score.total}/300点</p>${s.years.map((y,i)=>`<h3>第${y.year}期</h3>${formalBalance(y.balances,s.years[i-1]?.balances||null,'前期末比')}${formalPL(y.balances,s.years[i-1]?.balances||null,'前年比')}`).join('')}<h3>最終期の事業別収支</h3><div class="trend-scroll"><table class="trend-table"><thead><tr><th>部門</th><th>売上</th><th>部門利益</th><th>利息後利益</th></tr></thead><tbody>${s.segments.map(x=>`<tr><th>${x.id==='retail'?'釣具店':x.id==='hq'?'本社':x.id==='fishery'?'漁業':'不動産'}</th><td>${yen(x.sales)}</td><td>${signedYen(x.contribution)}</td><td>${signedYen(x.profit)}</td></tr>`).join('')}</tbody></table></div><p>店舗スタッフ${s.business.staff}人、不動産${s.business.properties.length}件、漁業${s.business.fishery?'あり':'なし'}。M&A ${s.ma==='sold'?'成約':'成約なし'}。</p><button id="rankingMenuRetry">順位へ戻る</button>`);}
const finalBeforeRanked=showFinalResult;
showFinalResult=function(){finalBeforeRanked();if(state.replay&&Ranked.snapshot(state).score&&!['offer','negotiate','confirm'].includes(state.expansion.ma?.phase))el('shopDialogBody').innerHTML+='<p id="rankStatus">'+safeText(rankedStatus())+'</p><button id="rankPublishPreview">完走記録を公開ランキングへ</button>';};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const ids=['rankingMenu','rankingMenuRetry','rankStartPreview','rankStartConfirm','rankRetry','rankPublishPreview','rankPublishConfirm','rankWithdrawPreview','rankWithdrawConfirm','rankLoadMonth'];if(!ids.includes(b.id)&&!b.dataset.rankDetail)return;b.disabled=true;try{
 if(['rankingMenu','rankingMenuRetry'].includes(b.id))await showRanking();else if(b.id==='rankStartPreview')openShop('新しいチャレンジの開始',`<p>${safeText(rankScenario?.scenario)}の共通シナリオを開業時点から始めます。株式払込・開業支出を済ませた状態です。現在の経営を復元用に１世代保存して入れ替えます。</p>${startingSalaryOptions('rankStartingSalary')}<button id="rankStartConfirm">保存してチャレンジを始める</button>`);else if(b.id==='rankStartConfirm')await startRanked();else if(b.id==='rankRetry'){await syncRanked();toast('操作履歴を同期しました。');}else if(b.id==='rankPublishPreview')publishRankPreview();else if(b.id==='rankPublishConfirm'){const name=el('rankNickname').value;await syncRanked();await rankRequest('/api/run/'+state.replay.id+'/publish',{name,revision:state.replay.ops.length});await showRanking();}else if(b.id==='rankWithdrawPreview')openShop('公開を取り下げる', '<p>このシナリオの自分の公開記録を削除します。ゲームのセーブは残ります。</p><button id="rankWithdrawConfirm">公開記録を取り下げる</button>');else if(b.id==='rankWithdrawConfirm'){await rankRequest('/api/run/'+state.replay.id+'/withdraw',{});await showRanking();}else if(b.dataset.rankDetail)await showRankDetail(b.dataset.rankDetail);else if(b.id==='rankLoadMonth'){const month=el('rankMonth').value,r=await rankRequest('/api/ranking?scenario='+encodeURIComponent(month));openShop(safeText(month)+'の順位',r.rows.map((x,i)=>`<p><button data-rank-detail="${safeText(x.id)}">${i+1}位 ${safeText(x.name)} · ${x.score}点</button></p>`).join('')||'<p>公開記録がありません。</p>');}
 }catch(err){toast(err.message);}finally{b.disabled=false;}});
const rankButton=document.createElement('button');rankButton.id='rankingMenu';rankButton.className='help-top';rankButton.textContent='ランキング';document.querySelector('.top').append(rankButton);
if(state.replay)syncRanked().catch(()=>{});
// Native disclosure keeps all commands reachable without filling a phone's first screen.
const commandMenu=document.createElement('details');commandMenu.className='command-menu';const commandSummary=document.createElement('summary');commandSummary.textContent='経営メニュー';const commandList=document.createElement('div');commandList.className='command-menu-list';for(const button of document.querySelectorAll('.top .help-top'))commandList.append(button);commandMenu.append(commandSummary,commandList);document.querySelector('.top').append(commandMenu);// Close before document capture handlers (bank/property) can stop propagation.
window.addEventListener('click',event=>{
 const button=event.target.closest?.('button');
 if(button&&!button.disabled&&commandList.contains(button))commandMenu.open=false;
},true);
